from pathlib import Path
import sys,yaml,json,re
B=Path('desk/drawer/plans/workspace-documental');sys.path.insert(0,str(B));import context_review as cr
R=Path('runs/subagents/20261031-finalizar-plan-workspace');p=B/'dag.yaml';d=yaml.safe_load(p.read_text());nodes={n['id']:n for n in cr.all_nodes(d)}
prior=json.loads((R/'round3-findings.json').read_text())
notes={
'WS11':'1 foco/historia/disposición locales es decisión técnica P07 específica; APIs reales soportan identidad/origen/documentos/links, no exige persistir preferencias en store ni backend nuevo. Contrato debe documentar ambos: API comprobada y estado local. 2 revisión es workflow de TaskDoc deskops (supervisor/Tester/evidencia en run), no firma humana adicional; se concreta en promoción. Scope limita solo contrato/enlaces, nunca aprobar recepción por autochequeo.',
'WS21':'Preview de render de buffer vs persistido es interacción que contrato WS11/12, catálogo WS09 y TaskDoc fijan antes de implementar. Aceptación invariante es mismo origen/revisión y buffer conservado, sin descarte sin confirmación y sin prometer guardado no observado. No se delega permiso ni fuente extra; ambos soportes tienen productor y se detiene si contrato falta. Dry-run recupera variante editable/G_SOURCE y protección de datos.',
'WS26.2':prior['WS26.2']+' Campo files ausente no prueba no-solapamiento: regla de «no comprobado» ante resolución dudosa y no heurística optimista lo cubre; TaskDoc/contrato WS12 deben completar archivos antes marcar capa lista. No se interpreta ausencia como autorización ready.',
'WS28':prior['WS28']+' Endpoints solo los autorizados por canal/efectos WS12 para verify/preparar/handoff; límite explícito prohíbe cierre HTTP sin excepción. Coordinador activo/canal de entrega es política/capability que produce WS12 según P03, no flag UI inventado. Si falta, lectura/preparación manual y no operación falsa.',
'WS32':'«Refinar ticket» significa refinar el alcance del candidato Scion existente al authorar futura TaskDoc de hijos y vincular origen (mismo pipeline), no obligación de que agregado edite archivo de ticket. external_reference suministra ruta exacta desk/drawer/tasks/task-correlacionar-intentos-scion-con-rundoc-y-closeout.md en deskops y output_scope entrega solo hijos. Promoción fija archivos/evidencia y evita segunda ejecución, según integration_mode/matriz WS06 y regla de alcance. Dry-run correcto sobre identidad local, aceptación hijos y dispatch separado.',
'WS33.1':'1 claves explícitas de scope gobiernan: mensajes por Hub/proyecto/conversación/mensaje; resultados por Hub/proyecto/intento/id fuente. Acceptance de importar conversación repetida es escenario para probar que ninguna de ambas clases se duplica, no agrega conversación a clave de resultados. 2 scope prohíbe vincular CUALQUIER mensaje/resultado sin id de intento existente; contrato WS12 define error/hueco de procedencia y TaskDoc el caso exacto antes implementar. No asignar por conversación ni inventar intento. Dry-run respeta backend/contrato/gates por efecto y no tablas Scion.',
'WS34.1':'Timeout/errores son contrato de operación WS12 por delta (canal, revisión, efectos/errores), igual que reply WS34.2 lo nombra; TaskDoc fija umbral concreto dentro contrato. Propio output FUTURO identifica WS12 contrato/canal y TaskDoc umbrales. No se inventa éxito/fallo Hub: aceptación exige respuesta observada y ausencia no equivale estado remoto. Es detalle de prueba/promoción con productor, no API/permiso ausente.',
'WS35':prior['WS35']+' Conversación es procedencia de mensajes definida por WS33.1; orden/agrupación visual se fija TaskDoc, sin nuevo modelo. Decisión explícita es de WS33.2 (scope WS33 agregado la nombra); WS32 aporta intento, no aprobación. Sin intento no se fabrica decisión vinculada ni aprobación; reglas backend/contrato WS12 conservan hueco de procedencia.',
'WS39':prior['WS39'],
'WS42':'1 pruebas usan store temporal real generado por CLI/modelos públicos (regla común), con materialización de entrada registrada válida/inválida según escenario TaskDoc; crear input de prueba no es generar/publicar destinos arbitrarios de materialización. No fake API ni destino de producto inventado. 2 versión/commit de artefactos/modelo/tools/store utilizados se registra por Executor en evidencia del run de la TaskDoc, como todo escenario verificable. 3 WS40 es alternativa, no dependencia obligatoria porque scope permite propio store temporal real; si se elige corpus futuro se espera su manifiesto, no se sustituye dato por mock. Dry-run/aceptación mantienen invalidas no operables y API SLDB real.'}
for line in (R/'runner-contract-final.log').read_text().splitlines():
 nid,ok,path=line.split(' ',2);a=Path(path);out=(a/'output.md').read_text();n=nodes[nid];assert ok=='ok'
 none=bool(re.search(r'AMBIGUEDADES[^\n]*\n+\s*(?:\*\*)?(?:ninguna|Ninguna)',out))
 if none:
  note='Comparación aceptada por contenido completo: propósito/resultado/repo/límites coinciden con contrato; dry-run identifica fuentes, cambios futuros, dependencias/transferencias y pruebas específicas, sin ejecutar. Gates técnicos se verifican por efecto propio, sin sustituirlos por permiso/UI o receipt vecino. Respeta estados reales/no disponibles, decisiones registradas y autorización futura separada. Ninguna ambigüedad real pendiente; no se acepta por token APTO.'
  if nid=='WS34.2':note+=' Timeout es fallo local de operación sin confirmación; jamás afirma resultado remoto del Hub no observado (límite de WS34.1/identidad WS32 y contrato WS12), observación no bloqueante del concilio separada.'
 else:
  note=notes.get(nid) or prior.get(nid);assert note,nid
 data,_=cr.bundle(d,n);assert cr.sha(data)==a.parent.name,nid
 assert cr.sha(cr.canonical(n).encode())==json.loads((a/'manifest.json').read_text())['node_contract_sha256'],nid
 cite=out[:out.upper().index('AMBIGUEDADES')].strip()
 (a/'disposition.md').write_text(f'# Executor comparison — {nid}, final per-effect contract input\n\nState: accepted_current\n\n## Reformulación examinada\n\n{cite}\n\n## Hallazgos/disposición contra intención\n\n{note}\n\nSe leyó y contrastó output completo (reformulación, ambigüedades, dry-run y futuro). Rúbrica: resultado/repo/límites, orden/autoridad, aceptación verificable, decisiones y efectos con dueño. Detalles asignados a contrato/TaskDoc no autorizan improvisación: si falta el contrato/capability, detener y registrar hueco. No se ejecuta producto ni se declara recepción. Ningún output/disposición anterior fue input del modelo.\n')
 n['context_review'].update(status='reviewed',input_sha256=cr.sha(data),contract_sha256=cr.sha(cr.canonical(n).encode()),evidence=[path])
d['status']='final_plan_reviewed';assert not cr.stale_reviews(d),cr.stale_reviews(d)
p.write_text(yaml.safe_dump(d,allow_unicode=True,sort_keys=False))
print('Final comparisons accepted; all 72 reviews current; no execution authorized.')
